from __future__ import annotations; import runpy; import shutil; import sys; from pathlib import Path; import pytest; sys.path.insert(0, str(Path(__file__).resolve().parents[2])); from common.runtime import check_toolchain_contract as contract; ROOT = Path(__file__).resolve().parents[2]
def _copy_contract_inputs(target_root: Path) -> None:
    for relative_path in ('toolchain.toml', '.python-version', '.node-version', '.nvmrc', '.tool-versions', '.npmrc', '.moon/toolchain.yml', 'apps/frontend/package.json', '.github/workflows/ci.yml', '.github/workflows/docs.yml', '.github/actions/setup-e2e-tests/action.yml', '.github/actions/setup-minio/action.yml', 'apps/backend/Dockerfile', 'apps/frontend/Dockerfile', 'docker-compose.yml'): source = ROOT / relative_path; target = target_root / relative_path; target.parent.mkdir(parents=True, exist_ok=True); shutil.copyfile(source, target)
def test_AC8_13_39_current_toolchain_contract_is_consistent() -> None: 'AC8.13.39'; assert contract.run_contract(ROOT) == 0
def test_AC8_13_39_contract_fails_when_node_version_drifts(tmp_path: Path) -> None:
    'AC8.13.39'; _copy_contract_inputs(tmp_path); (tmp_path / '.node-version').write_text('25.9.0\n', encoding='utf-8'); assert contract.run_contract(tmp_path) == 1; 'AC8.13.39'; _m1_tmp = tmp_path / '_m1'; _m1_tmp.mkdir(exist_ok=True); 'AC8.13.39'; _copy_contract_inputs(_m1_tmp); _m1_dockerfile = _m1_tmp / 'apps/backend/Dockerfile'; _m1_dockerfile.write_text(_m1_dockerfile.read_text(encoding='utf-8').replace('ARG PYTHON_IMAGE=python:3.12.12-slim', 'ARG PYTHON_IMAGE=python:3.12-slim'), encoding='utf-8'); assert contract.run_contract(_m1_tmp) == 1; 'AC8.13.39'; _m2_tmp = tmp_path / '_m2'; _m2_tmp.mkdir(exist_ok=True); 'AC8.13.39'; _copy_contract_inputs(_m2_tmp); _m2_package_json = _m2_tmp / 'apps/frontend/package.json'; _m2_package_json.write_text(_m2_package_json.read_text(encoding='utf-8').replace('"node": "20.19.0"', '"node": ">=20"'), encoding='utf-8'); assert contract.run_contract(_m2_tmp) == 1; 'AC8.13.39'; _m3_tmp = tmp_path / '_m3'; _m3_tmp.mkdir(exist_ok=True); 'AC8.13.39'; _copy_contract_inputs(_m3_tmp); _m3_moon_toolchain = _m3_tmp / '.moon/toolchain.yml'; _m3_moon_toolchain.write_text(_m3_moon_toolchain.read_text(encoding='utf-8').replace("version: '20.19.0'", "version: '25.9.0'"), encoding='utf-8'); assert contract.run_contract(_m3_tmp) == 1; 'AC8.13.39'; _m4_tmp = tmp_path / '_m4'; _m4_tmp.mkdir(exist_ok=True); 'AC8.13.39'
    with pytest.raises(FileNotFoundError): contract.load_toolchain(_m4_tmp)
    'AC-testing.toolchain.1'; _m5_tmp = tmp_path / '_m5'; _m5_tmp.mkdir(exist_ok=True); 'AC-testing.toolchain.1'; _copy_contract_inputs(_m5_tmp); _m5_target = _m5_tmp / '.github/actions/setup-minio/action.yml'; _m5_image = contract.load_toolchain(_m5_tmp)['images']['minio']; _m5_content = _m5_target.read_text(encoding='utf-8').replace('name: Start MinIO', 'name: Start object storage', 1); _m5_target.write_text(_m5_content.replace(_m5_image, 'invalid.example/minio:drift', 1)); assert contract.run_contract(_m5_tmp) == 1; 'AC-testing.toolchain.1'; _m6_tmp = tmp_path / '_m6'; _m6_tmp.mkdir(exist_ok=True); 'AC-testing.toolchain.1'; _copy_contract_inputs(_m6_tmp); _m6_action_file = _m6_tmp / '.github/actions/setup-minio/action.yml'; _m6_action_file.unlink(); assert contract.run_contract(_m6_tmp) == 1
@pytest.mark.parametrize(('path', 'image_key', 'occurrence'), [(path, image, 0) for path in ('.github/actions/setup-minio/action.yml', 'docker-compose.yml') for image in ('minio', 'minio_client')])
def test_minio_image_drift_fails_in_each_environment(tmp_path: Path, path: str, image_key: str, occurrence: int) -> None: 'AC-testing.toolchain.1'; _copy_contract_inputs(tmp_path); image = contract.load_toolchain(tmp_path)['images'][image_key]; target = tmp_path / path; content = target.read_text(encoding='utf-8'); parts = content.split(image); assert len(parts) > occurrence + 1; before = image.join(parts[:occurrence + 1]); after = image.join(parts[occurrence + 1:]); target.write_text(before + 'invalid.example/minio:drift' + after, encoding='utf-8'); assert contract.run_contract(tmp_path) == 1
def test_AC8_13_39_cli_accepts_explicit_repo_root(monkeypatch: pytest.MonkeyPatch) -> None: 'AC-testing.toolchain.1 AC8.13.39'; monkeypatch.setattr(sys, 'argv', ['check_toolchain_contract.py', '--repo-root', str(ROOT)]); assert contract.main() == 0
@pytest.mark.parametrize('quote', ['', "'", '"'])
def test_compose_image_formatting_is_not_drift(tmp_path: Path, quote: str) -> None:
    'AC-testing.toolchain.1'; _copy_contract_inputs(tmp_path); image = contract.load_toolchain(tmp_path)['images']['minio']
    for path in ('docker-compose.yml',): target = tmp_path / path; target.write_text(target.read_text().replace(f'image: {image}', f'image:  {quote}{image}{quote}  # same immutable image'))
    assert contract.run_contract(tmp_path) == 0
@pytest.mark.parametrize('quote', ['', "'", '"'])
def test_action_image_formatting_is_not_drift(tmp_path: Path, quote: str) -> None: 'AC-testing.toolchain.1'; _copy_contract_inputs(tmp_path); image = contract.load_toolchain(tmp_path)['images']['minio']; target = tmp_path / '.github/actions/setup-minio/action.yml'; target.write_text(target.read_text().replace(image, f'{quote}{image}{quote}')); assert contract.run_contract(tmp_path) == 0
def test_AC8_13_39_module_entrypoint_exits_with_status(monkeypatch: pytest.MonkeyPatch) -> None:
    'AC8.13.39'; monkeypatch.setattr(sys, 'argv', ['check_toolchain_contract.py', '--repo-root', str(ROOT)])
    with pytest.raises(SystemExit) as exc_info: runpy.run_path(Path(contract.__file__).as_posix(), run_name='__main__')
    assert exc_info.value.code == 0
